    "verified": "TRUE",
    "photo_url": "https://hidden-pine-cbff.mirbekbekov.workers.dev/uploads/object_67_1.jpg | https://hidden-pine-cbff.mirbekbekov.workers.dev/uploads/object_67_2.jpg | https://hidden-pine-cbff.mirbekbekov.workers.dev/uploads/object_67_3.jpg | https://hidden-pine-cbff.mirbekbekov.workers.dev/uploads/object_67_4.jpg | https://hidden-pine-cbff.mirbekbekov.workers.dev/uploads/object_67_5.jpg",
    "tg_link": "https://t.me/Liberterra_kg_bot?start=object_67",
    "status": "опубликован",
    "latitude": "",
    "longitude": "",
    "id": "67",
    "description": "🏡 Продаётся жилой дом с кошарой на участке 51,86 сотки\n📍 Московский район, с. Асылбаш\n💰 Стоимость: 63 000 $\n\nПредлагается земельный участок общей площадью 5 186 м² (51,86 сотки) с жилым домом и капитальными хозяйственными строениями.\n\nХарактеристики объекта:\nПлощадь участка — 5 186 м²;\nОбщая площадь строений — 600,5 м²;\nЖилой дом — готов к проживанию;\nКошара — 566 м², капитальное строение.\n\nДокументы:\nГосударственный акт на земельный участок;\nДоговор купли-продажи на строения;\nБез обременений.\n\nОбъект может подойти для:\nведения фермерского хозяйства;\nсодержания скота;\nсклада или небольшого производства;\nпроживания с использованием хозяйственных построек.\n\n📍 Участок расположен рядом с крестьянским хозяйством «Санги». Имеет удобный подъезд, поблизости находится необходимая инфраструктура.\n\n📞 Для получения дополнительной информации и организации просмотра свяжитесь с нами.\n\n🏡 51,86 сотых жер тилкеси менен турак үй жана мал сарайы сатылат\n📍 Москва району, Асылбаш айылы\n💰 Баасы: 63 000 $\n\nЖалпы аянты 5 186 м² (51,86 сотых) болгон жер тилкеси, турак үйү жана капиталдык мал сарайы менен кошо сатылат.\n\nОбъекттин мүнөздөмөлөрү:\n\nЖер тилкесинин аянты — 5 186 м²;\nИмараттардын жалпы аянты — 600,5 м²;\nТурак үй — жашоого даяр;\nМал сарайы — 566 м², бекем курулган капиталдык имарат.\n\nДокументтери:\n\nЖерге мамлекеттик акт (Госакт);\nИмараттарга сатып алуу-сатуу келишими;\nКамак же башка чектөөлөр жок.\n\nТөмөнкү максаттар үчүн ылайыктуу:\n\nфермердик чарба жүргүзүүгө;\nмал багууга;\nкампа же чакан өндүрүш уюштурууга;\nтурак жай жана чарбаны бир жерде алып барууга.\n\n📍 Объект «Санги» дыйкан чарбасынын жанында жайгашкан. Ыңгайлуу кире бериши бар, жакын жерде керектүү инфраструктура жайгашкан.\n\n📞 Кошумча маалымат алуу же объектти көрүү үчүн биз менен байланышыңыз.",
