    "description": "Офис в бизнес-центре | Московская × Эркиндик\n📍 Адрес: г. Бишкек, пересечение ул. Московской и бульвара Эркиндик\nБизнес-центр расположен в одном из ключевых деловых районов города. В непосредственной близости — государственные учреждения, банки, рестораны, гостиницы и другие объекты городской инфраструктуры.\nДоступный офис\n13 этаж\nПлощадь офиса — 256,5 м²\nТерраса — 189 м² — предоставляется без дополнительной оплаты.\nПлощадь лестнично-лифтового холла не входит в арендуемую площадь.\nОфис передаётся без мебели, что позволяет арендатору самостоятельно организовать пространство с учётом формата и требований компании.\nОснащение и безопасность\nсистема отопления и кондиционирования на базе фанкойлов;\nоборудование Aermec;\nвысокоскоростной интернет и современные коммуникации;\nрезервный дизельный генератор;\nсобственная трансформаторная подстанция;\nэлектронная система контроля доступа;\nкруглосуточная охрана и видеонаблюдение;\nавтоматическая пожарная сигнализация и система пожаротушения;\nсейсмостойкая конструкция здания.\nИнфраструктура бизнес-центра\nВ здании расположен KICB.\nДля арендаторов доступны:\nресторан;\nконференц-залы;\nфитнес-зал;\nбассейн;\nфинская сауна и хаммам;\nмассажные кабинеты;\nкофе-бар.\nПарковка\nохраняемая наземная и подземная парковка;\nвъезд по зарегистрированным государственным номерам;\nпрямой доступ из подземного паркинга на лифте;\n2 парковочных места закреплены за предлагаемым офисом.\nСтоимость парковки — 150 USD/месяц за одно место.\nСтоимость аренды\nВариант 1 — 30 USD/м²\nС учётом налогов, без торга.\nВ стоимость включены:\nотопление;\nводоснабжение и канализация;\nуборка мест общего пользования;\nвывоз мусора;\nэксплуатация и обслуживание здания.\nДополнительно оплачиваются:\nэлектроэнергия;\nинтернет;\nтелефонная связь.\nВариант 2 — 28 USD/м²\nС учётом налогов, без торга.\nВ стоимость включены:\nуборка мест общего пользования;\nэксплуатация и обслуживание здания.\nДополнительно оплачиваются:\nотопление;\nводоснабжение и канализация;\nэлектроэнергия;\nинтернет;\nтелефонная связь.\nУсловия аренды\nминимальный срок аренды — 12 месяцев;\nоплата — ежеквартально, на условиях предоплаты;\nпервый платёж — в течение 5 банковских дней после подписания договора;\nрасчёты производятся в сомах по курсу НБ КР на дату оплаты;\nобеспечительный депозит — 2 месяца арендной платы.\nОфис подойдёт для компании, которой важны престижная деловая локация, представительность бизнес-центра, развитая инфраструктура и возможность организовать просторное рабочее пространство с собственной террасой.",
